+fn load_config() -> SherpaConfig {
+    SherpaConfig::default_path()
+        .ok()
+        .and_then(|p| SherpaConfig::load(&p).ok())
+        .unwrap_or_default()
+}
+
+fn validate_token(headers: &HeaderMap) -> Result<()> {
+    let config = load_config();
+    let expected_token = config
+        .agent
+        .token
+        .ok_or_else(|| Error::Unauthorized("Agent token not configured".to_string()))?;
+
+    let provided_token = extract_bearer_token(headers)
+        .ok_or_else(|| Error::Unauthorized("Missing Bearer token".to_string()))?;
+
+    if provided_token != expected_token {
+        return Err(Error::Unauthorized("Invalid agent token".to_string()));
+    }
+
+    Ok(())
+}
+
+fn generate_agent_token() -> String {
+    use std::collections::hash_map::DefaultHasher;
+    use std::hash::{Hash, Hasher};
+    use std::time::{SystemTime, UNIX_EPOCH};
+
+    let nanos = SystemTime::now()
+        .duration_since(UNIX_EPOCH)
+        .expect("system clock before UNIX epoch")
+        .as_nanos();
+    let pid = std::process::id();
+
+    let mut hasher = DefaultHasher::new();
+    nanos.hash(&mut hasher);
+    pid.hash(&mut hasher);
+    let h1 = hasher.finish();
+
+    (nanos + 1).hash(&mut hasher);
+    let h2 = hasher.finish();
+
+    format!("agent-{h1:016x}{h2:016x}")
+}
