+            } else {
+                match step.status {
+                    StepStatus::Planned => "Planned",
+                    StepStatus::ReadyForReview => "ReadyForReview",
+                    StepStatus::Reviewed => "Reviewed",
+                }
+            };
+            serde_json::json!({
+                "number": i + 1,
+                "title": step.title,
+                "file_count": step.file_refs.len(),
+                "status": status,
+                "is_new": step.status == StepStatus::ReadyForReview && !validated,
+            })
+        })
+        .collect()
